'use client';

import { useState } from 'react';
import { motion } from 'framer-motion';
import { Search, Globe, UserCircle } from 'lucide-react';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import PrimaryButton from '@/components/Primarybutton';

const PropertyDetail = () => {
  const [city, setCity] = useState("");
  const [checkIn, setCheckIn] = useState('');
  const [checkOut, setCheckOut] = useState('');
  const [nights, setNights] = useState(0);
  const [showDropdown, setShowDropdown] = useState(false);
  const images = [
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/a0638242-53de-462a-b6d9-bac98863f931.jpeg?im_w=960',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/5a9b17fc-0fe1-474f-9be3-fed3c4913d13.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/f552426b-52af-40ba-bb08-214eeb14937a.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/1b375715-f77e-47f0-bd4f-b5bfbc73db53.jpeg?im_w=720',
    'https://a0.muscache.com/im/pictures/hosting/Hosting-1158357014875094502/original/719ce935-cb8d-4638-b107-ca0625de1323.jpeg?im_w=720'
  ];
  const [selectedImage, setSelectedImage] = useState(images[0]);

  const router = useRouter();

  const pricePerNight = 5143;
  const cleaningFee = 200;
  const serviceFee = 3659;
  const totalCost = nights * pricePerNight + cleaningFee + serviceFee;



  const calculateNights = () => {
    if (checkIn && checkOut) {
      const start = new Date(checkIn);
      const end = new Date(checkOut);
      setNights(Math.ceil((end.getTime() - start.getTime()) / (1000 * 3600 * 24)));
    }
  };

  return (
    <motion.div 
      className="max-w-[1440px] mx-auto"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8 }}
    >
      {/* Header */}
      <motion.header 
        className="flex justify-between items-center py-4 px-8 border-b"
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.6 }}
      >
        <div className="text-red-500 font-bold text-2xl">Avacasa</div>
        <div className="flex items-center gap-4 relative">
          <motion.div 
            className="text-gray-600 cursor-pointer hover:text-gray-800"
            whileHover={{ scale: 1.1 }}
            onClick={() => router.push('/earnings')}
          >
            Avacasa your home
          </motion.div>
          <Globe size={20} className="cursor-pointer text-gray-600 hover:text-gray-800" />
          <motion.div 
            className="flex items-center border border-gray-300 px-3 py-2 rounded-full gap-2 cursor-pointer hover:shadow-md"
            whileTap={{ scale: 0.95 }}
            onClick={() => setShowDropdown(!showDropdown)}
          >
            <UserCircle size={20} className="text-gray-600" />
          </motion.div>

          {/* Dropdown */}
          {showDropdown && (
            <motion.div 
              className="absolute top-12 right-0 bg-white shadow-md rounded-lg border border-gray-200 w-40"
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3 }}
            >
              <div className="px-4 py-2 hover:bg-gray-100 cursor-pointer" onClick={() => router.push('/signup')}>Signup</div>
              <div className="px-4 py-2 hover:bg-gray-100 cursor-pointer" onClick={() => router.push('/login')}>Login</div>
            </motion.div>
          )}
        </div>
      </motion.header>

      {/* Image Gallery */}
      <div className="px-4 sm:px-8 py-8">
        <motion.div 
          className="grid grid-cols-1 md:grid-cols-2 gap-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1 }}
        >
          <Image src={selectedImage} alt="Main Image" width={700} height={400} className="rounded-lg object-cover w-full h-[400px]" />
          <div className="grid grid-cols-3 sm:grid-cols-2 gap-4">
            {images.slice(1).map((img, index) => (
              <motion.div 
                key={index}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setSelectedImage(img)}
              >
                <Image src={img} alt={`Image ${index + 1}`} width={340} height={200} className="rounded-lg object-cover w-full h-[190px] cursor-pointer" />
              </motion.div>
            ))}
          </div>
        </motion.div>
      </div>

      {/* Reserve Section */}
      <motion.div 
        className="border border-gray-300 px-8 mr-12 ml-32 rounded-xl shadow-md"
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={{ duration: 0.6 }}
      >
        <p className="text-xl font-semibold">
          ₹<span className="line-through text-gray-400">7,000</span> <span className="text-black font-bold">₹{pricePerNight}</span> night
        </p>
        <div className="flex gap-4 mt-4">
          <motion.input 
            type="date" value={checkIn} onChange={(e) => setCheckIn(e.target.value)}
            className="border rounded-md p-2 w-full"
            onBlur={calculateNights}
            whileFocus={{ scale: 1.02 }}
          />
          <motion.input 
            type="date" value={checkOut} onChange={(e) => setCheckOut(e.target.value)}
            className="border rounded-md p-2 w-full"
            onBlur={calculateNights}
            whileFocus={{ scale: 1.02 }}
          />
        </div>

        <motion.button 
          onClick={() => alert(`Reservation confirmed! Total: ₹${totalCost.toLocaleString()}`)}
          className="bg-pink-500 text-white w-full mt-4 py-2 rounded-md font-semibold"
          whileHover={{ scale: 1.05 }}
        >
          Reserve
        </motion.button>
      </motion.div>
    </motion.div>
  );
};

export default PropertyDetail;